/* Orden futbolístico de los puestos. POSD ya está escrita de portero a delantero
   centro, así que el índice de su clave ES el orden natural: no hace falta
   inventar otra tabla. Antes la columna POS se comparaba como texto y salía
   alfabética (CAD, DC, DFC, ED, EI, LD…), con el portero en mitad del plantel. */
function ordenPos(j){const i=Object.keys(POSD).indexOf(j.posE||j.pos);return i<0?99:i;}
/* Única clave que necesita traducción; el resto son campos del propio jugador. */
function valOrden(j,k){return k==='posE'?ordenPos(j):j[k];}
let ordJug={k:'ovr',asc:false};
/* Al estrenar una columna se arranca en el sentido que el jugador espera:
   los números de mayor a menor (el mejor primero) y los textos de la A a la Z. */
function ordenar(k){if(ordJug.k===k)ordJug.asc=!ordJug.asc;else{ordJug.k=k;ordJug.asc=(k==='posE'||k==='nombre');}render();}
function vJugadores(){
  const js=plantelDe(G.miClub).slice().sort((a,b)=>{
    const va=valOrden(a,ordJug.k),vb=valOrden(b,ordJug.k);
    if(typeof va==='string')return ordJug.asc?va.localeCompare(vb):vb.localeCompare(va);
    return ordJug.asc?va-vb:vb-va;
  });
  const flecha=k=>ordJug.k===k?(ordJug.asc?' ▲':' ▼'):'';
  const h=(k,l)=>`<th onclick="ordenar('${k}')" class="${ordJug.k===k?'on':''}">${l}${flecha(k)}</th>`;
  /* Los encabezados ya ordenaban, pero eso solo lo sabe quien lee la letra gris
     del pie. La barra hace visible en el menú algo que el juego ya sabía hacer. */
  const bOrd=(k,l)=>`<button class="mini ${ordJug.k===k?'':'sec'}" onclick="ordenar('${k}')">${l}${flecha(k)}</button>`;
  const barraOrden=`<div class="card"><small>ORDENAR EL PLANTEL</small>
    <div class="btnrow wrap">${bOrd('ovr','Media')}${bOrd('posE','Posición')}${bOrd('edad','Edad')}${bOrd('valor','Valor')}${bOrd('forma','Forma')}${bOrd('nombre','Nombre')}</div>
    <p class="mut" style="margin:4px 0 0">Toca dos veces la misma para invertir el sentido. Los encabezados de la tabla ordenan igual.</p></div>`;
  const prog=plantelDe(G.miClub).filter(j=>j.dTemp>0).sort((a,b)=>b.dTemp-a.dTemp);

