/* ---------- LISTA DE TRANSFERIBLES ----------
   j.transferible ya cambiaba el juego (el sorteo semanal de ofertas mete al
   listado DOS veces en la bolsa), pero solo se encendía si el propio jugador
   lo pedía en un evento. Desde el menú no había manera: esto la abre. No se
   toca j.rolClub porque el rol pasa por aceptaRol() y tiene su propia mesa. */
function listarTransferible(pid){
  const j=G.jug[pid];if(!j||j.club!==G.miClub)return;
  if(j.transferible)return;
  j.transferible=true;
  /* Que le digan a la cara que sobra tiene precio: la moral es lo que
     fuerzaJug() lee cada minuto, así que esto se nota en la cancha. */
  j.moral=clamp(j.moral-8,10,99);
  if(j.mente)j.mente.ansiedad=clamp(j.mente.ansiedad+8,0,100);
  noticia("En la lista de transferibles",j.nombre+" queda oficialmente ofrecido al mercado. Se lo tomó mal, pero a partir de ahora van a llegar ofertas por él.");
  render();guardarLS();
}
/* ---------- RESCISIÓN DE CONTRATO ----------
   Echar a un jugador no puede ser un botón gratis: el contrato se paga igual.
   El finiquito son las semanas que le quedaban por su sueldo, rebajadas por lo
   que se acaba pactando en la mesa, y encima el agente cobra comisión. Todo lo
   que se toca después (moral, humor del clan, ánimo, funa, confianza del
   agente, exMio) tiene lector real en el juego: no se escribe ninguna etiqueta
   que nadie lea. */
function semanasContrato(j){
  const total=(G.semanas&&G.semanas.length)||42;
  /* j.años incluye la temporada en curso (se descuenta en el cierre de año),
     así que el año actual cuenta solo por las semanas que faltan y los demás
     enteros. Mínimo cuatro: nadie firma una salida por cero. */
  return Math.max(4,(total-G.sem)+Math.max(0,(j.años||1)-1)*total);
}
function finiquitoDe(j){
  const ag=agenteDe(j);
  /* 0,6 = lo que se arregla de verdad: nadie paga el 100% del contrato, pero un
     tiburón te deja mucho más cerca del 100% que un formador (ag.f). */
  let base=semanasContrato(j)*j.sueldo*0.6*ag.f;
  if(j.pideSalir)base*=0.55;          // si ya se quiere ir, la salida es barata
  else if(j.transferible)base*=0.80;  // ya listado: media rebaja
  return Math.max(1000,Math.round(base/1000)*1000);
}
function rescindirJug(pid){
  const j=G.jug[pid];if(!j||j.club!==G.miClub)return;
  if(esAyudante()){toast("Rescindir contratos no es cosa del ayudante de campo");return;}
  if(j.prestamo){toast("Está cedido: primero tiene que volver");return;}
  if(plantelDe(G.miClub).length<=18){toast("Plantel muy corto: no puedes bajar de 18 fichas");return;}
  const ag=agenteDe(j),fin=finiquitoDe(j),com=Math.round(fin*ag.com);
  if(G.saldo<fin+com){toast("No alcanza el finiquito: "+fmt$(fin+com));return;}
  /* Doble toque, igual que vender el club o borrar la partida: es irreversible */
  if(vista.confResc!==pid){vista.confResc=pid;render();return;}
  vista.confResc=null;
  guardarDeshacer("rescindir a "+j.nombre);
  mov(-fin,"Finiquito: "+j.nombre);
  mov(-com,"Comisión de salida del agente "+ag.n);
  const pesado=esIdolo(j)||!!j.capitan;
  const eraCap=!!j.capitan;
  const clan=(G.camarilla||[]).find(g=>g.miembros.includes(j.id));
  /* El golpe va a j.moral, que es lo que el motor consulta para resolver cada
     minuto: esto se NOTA jugando. A los de su camarilla les duele el doble. */
  const golpe=pesado?R(7,13):(j.ovr>=G.clubes[G.miClub].rep?R(4,8):R(1,4));
  for(const x of plantelDe(G.miClub)){
    if(x.id===pid)continue;
    const cerca=!!(clan&&clan.miembros.includes(x.id));
    x.moral=clamp(x.moral-golpe*(cerca?2:1),10,99);
    if(x.mente)x.mente.ansiedad=clamp(x.mente.ansiedad+Math.round(golpe*(cerca?1.4:0.6)),0,100);
  }
  if(clan)clan.humor=clamp((clan.humor||0)-R(10,25),-100,100);
  G.animo=clamp((G.animo||60)-(pesado?R(8,16):R(1,4)),0,100);
  if(pesado)G.funa=clamp((G.funa||0)+R(10,20),0,100);
  /* El agente no olvida quién le rompió un contrato: G.agConf se lee al ofertar
     por cualquiera de sus representados y al cerrar un traspaso. */
  const conf=(G.agConf=G.agConf||{});
  conf[ag.n]=(conf[ag.n]||0)-2;
  /* Sale por la puerta de atrás: si otro club lo ficha, la ley del ex se
     activará EN SU CONTRA el día que te lo cruces. */
  j.exMio={año:G.año,malo:true};
  j.club='';j.libre=true;j.años=0;j.pide=j.sueldo;
  j.transferible=false;j.capitan=false;j.renTag=null;
  G.libres=G.libres||[];G.libres.push(j);
  delete G.jug[pid];
  /* Listas que guardan ids sueltos: si no se limpian quedan apuntando a un
     jugador que ya no está en G.jug. */
  G.renov=(G.renov||[]).filter(x=>x!==pid);
  G.prioridad=(G.prioridad||[]).filter(x=>x!==pid);
  G.seguim=(G.seguim||[]).filter(x=>x!==pid);
  G.ofertasIn=(G.ofertasIn||[]).filter(o=>o.pid!==pid);
  if(G.renovNeg&&G.renovNeg.pid===pid)G.renovNeg=null;
  if(G.negoc&&G.negoc.pid===pid)G.negoc=null;
  /* Sin capitán el camarín se queda sin jerarquía (vCamarin y la sala de prensa
     lo leen): el brazalete se pasa con el mismo criterio con que se reparte al
     generar el plantel — el mejor de los de 27 en adelante. */
  if(eraCap){
    const pl=plantelDe(G.miClub);
    const rel=pl.filter(x=>x.edad>=27).sort((a,b)=>b.ovr-a.ovr)[0]||pl.slice().sort((a,b)=>b.ovr-a.ovr)[0];
    if(rel){rel.capitan=true;rel.moral=clamp(rel.moral+8,10,99);}
  }
  vista.fichaJug=null;
  noticia("Rescisión de contrato",
    j.nombre+" deja el club por la puerta de atrás. Se le pagan "+fmt$(fin)+" de finiquito más "+fmt$(com)+
    " de comisión y queda libre. "+(pesado?"Era de la casa: el vestuario y la hinchada lo van a hacer notar durante semanas.":"El camarín tomó nota."));
  post(pesado?'BOMBA: '+esc(j.nombre)+' rescinde y se va. En la puerta del estadio no lo perdonan.'
             :'Rescisión: '+esc(j.nombre)+' deja el plantel.',pesado?'hincha':'medio',pesado?2.6:1.2);
  sfx('plata');
  armarXI();armarCamarillas();render();guardarLS();
}

