/* ---------- FICHA DE UN CLUB CUALQUIERA ----------
   vista.fichaClub llevaba desde el principio con tres sitios que la LIMPIAN
   (setTab, setSub y el botón ATRÁS del móvil en dinastiaAtras) y ninguno que
   la escribiera ni la pintara: media pieza montada. Esto la termina. */
function abrirClub(cid){if(!G||!G.clubes[cid])return;vista.fichaClub=cid;vista.fichaJug=null;render();}
function cerrarClub(){vista.fichaClub=null;render();}
function vFichaClub(cid){
  const c=G.clubes[cid];
  if(!c)return '<div class="card">Ese club ya no existe.</div>';
  const mio=cid===G.miClub;
  /* La media que se enseña es la que TU red de ojeo alcanza a estimar: ovrNum
     ya aplica el error por país y el sesgo del ojeador, y devuelve el número
     exacto si el jugador es tuyo o está ojeado. Con el mercado a ciegas ni
     siquiera se da un número: se traduce con ESCALA_CIEGA, la misma tabla que
     usa la ficha del jugador. */
  const est=j=>ovrNum(j);
  const ciego=!mio&&!!(G.ajustes&&G.ajustes.ciego);
  const prom=a=>a.length?Math.round(a.reduce((s,j)=>s+est(j),0)/a.length):0;
  const txtMed=v=>ciego?(ESCALA_CIEGA.find(x=>v>=x[0])||ESCALA_CIEGA[ESCALA_CIEGA.length-1])[1]:String(v);
  const pl=plantelDe(cid).slice().sort((a,b)=>(ordenPos(a)-ordenPos(b))||(est(b)-est(a)));
  const once=pl.slice().sort((a,b)=>est(b)-est(a)).slice(0,11);
  const pos=posDe(cid);
  const masa=pl.reduce((s,j)=>s+j.sueldo,0);
  const acaban=pl.filter(j=>j.años<=1).length;
  const liga=c.pais==='CHI'?('División '+c.div):esc((PAISES_LIGAS[c.pais]||{}).liga||'Liga');
  const dt=dtDe(cid);
  return `<div class="card">
    <div class="btnrow" style="margin-bottom:4px"><button class="lnk" onclick="cerrarClub()">← volver</button>
      ${mio?'':`<button class="mini sec" onclick="cerrarClub();setTab('finanzas','mercado')">💼 Ir al mercado</button>`}</div>
    <div class="fichaTop">${escudo(c,62)}<div style="flex:1"><b class="big" style="font-size:19px">${esc(c.nombre)}</b><br>
      <small>${esc(nombrePais(c.pais))} · ${liga}${pos>0?' · '+pos+'°':''}</small><br>
      <small class="mut">🎩 DT ${esc(dt.n)} · ${esc(dt.d)}</small><br>
      <small class="mut">Forma ${chipsForma(c.forma)||'—'}</small></div>
      <div style="text-align:right">${jerseySVG(c.c1,c.c2,kitDe(c),46)}</div>
    </div>
    <div class="grid2 mt">
      <div><small>MEDIA DEL PLANTEL</small><div class="big" style="font-size:17px">${txtMed(prom(pl))}</div></div>
      <div><small>MEDIA DEL MEJOR ONCE</small><div class="big" style="font-size:17px">${txtMed(prom(once))}</div></div>
    </div>
    <div class="row2"><span>Reputación</span><b>${c.rep}</b></div>
    <div class="row2"><span>Aforo del estadio</span><b>${(c.cap||0).toLocaleString('es-CL')}</b></div>
    <div class="row2"><span>Fichas en el plantel</span><b>${pl.length}</b></div>
    <div class="row2"><span>Masa salarial</span><b>${fmt$(masa)}/sem</b></div>
    ${c.st?`<div class="row2"><span>Campaña</span><b>${c.st.pj} PJ · ${c.st.pg}G ${c.st.pe}E ${c.st.pp}P · ${c.st.pts} pts</b></div>`:''}
    ${(!mio&&esClasico(G.clubes[G.miClub],c))?'<div class="alerta">🔥 Es tu clásico. Fichar aquí te lo va a cobrar la hinchada.</div>':''}
  </div>
  <div class="card pad0"><table>
    <tr><th>POS</th><th>NOMBRE</th><th>ED</th><th>MED</th><th>AÑOS</th><th>VALOR</th></tr>
    ${pl.map(j=>`<tr class="tap ${(!mio&&j.años<=1)?'alertRow':''}" onclick="abrirJug('${j.id}')">
      <td class="pos ${j.pos}">${j.posE||j.pos}</td>
      <td>${esc(j.nombre)}${j.capitan?' ⓒ':''}${j.lesion>0?' 🩹':''}${j.susp>0?' 🚫':''}${j.prestamo?' 📤':''}</td>
      <td>${j.edad}</td><td><b>${ovrTxt(j)}</b></td><td>${j.años}${j.años<=1?' ⚠':''}</td><td>${fmt$(j.valor)}</td></tr>`).join('')
      ||'<tr><td colspan="6" class="mut">Este club no tiene jugadores registrados.</td></tr>'}
  </table></div>
  <p class="mut">${mio?'Tu propio plantel, leído con la misma vara que usas para mirar a los demás.'
    :'Toca a cualquiera para abrir su ficha y negociar. ⚠ = último año de contrato ('+acaban+' en esa situación): desde la semana 24 se pueden precontratar. La media que ves es hasta donde llega tu red de ojeo.'}</p>`;
}

